# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatorMixin, TimestampMixin


class ExplorerM2mTrackWaypoint(TimestampMixin, CreatorMixin, Base):
    __tablename__ = "explorer_m2m_track_waypoint"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    slot_position: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        comment=(
            "Zero-based ordering position of this waypoint visit along the "
            "recorded track."
        ),
    )
    track_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_track.id", ondelete="CASCADE"),
        nullable=False,
        comment=(
            "FK to explorer_agg_track with CASCADE delete. The recorded GPS "
            "activity during which this waypoint was visited."
        ),
    )
    waypoint_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_sub_waypoint.id", ondelete="CASCADE"),
        nullable=False,
        comment=(
            "FK to explorer_sub_waypoint with CASCADE delete. The waypoint "
            "visited during this track."
        ),
    )
